"""Curated Premiere-specific reference gaps found by comparison with the supplied AE manual.
Design approach only is borrowed: deeper symptom taxonomy and more alphabetized vocabulary.
All entries below are independently authored for Premiere and require no AE functionality.
"""

def extend_references(glossary,troubles,recipes):
    # (term, plain-language definition, practical Premiere example, prerequisite lesson number)
    terms = [
      ('A-roll','Primary narrative footage, typically the speaker or principal action; the label describes editorial role, not a file type.','Interview explanation stays audible under the cutaway.',34),
      ('Action safe','A historical display boundary used to avoid placing essential action too near an edge; modern platforms have their own overlays.','Check delivery-specific phone interface overlays.',62),
      ('Active monitor','The panel currently receiving keyboard commands, which changes the meaning of some keys.','J/K/L may operate the Source Monitor or timeline depending on focus.',19),
      ('Adjustable bitrate','Encoder data rate controlled by a target and sometimes a maximum, rather than a constant amount per frame.','Test VBR target and maximum on a motion-heavy passage.',86),
      ('Alpha channel','Per-pixel transparency information; formats and encoders must explicitly support it.','A graphic master with an alpha-capable codec composites over later footage.',88),
      ('Amplitude','Signal strength, commonly shown as a waveform; audio meters usually display level on a logarithmic dB scale.','Clip peaks are higher in some spoken syllables than others.',38),
      ('Artifact','Unwanted visible or audible distortion introduced by source capture, processing or compression.','Banding in a gradient or blockiness in fast motion.',85),
      ('Aspect-ratio mismatch','When image shape differs from its intended display or sequence, causing stretch, letterbox, pillarbox or crop.','A 4:3 archive shot needs intentional framing in a 16:9 sequence.',3),
      ('Audio conforming','Preparation of decoded or resampled audio for reliable timeline use; it may generate temporary media-cache data.','A compressed audio clip can need conforming before waveform playback.',92),
      ('B-frame','A compressed picture that can be predicted from other frames; not every codec uses the same prediction structure.','Long-GOP footage may require extra decode work during random scrubbing.',84),
      ('Bit depth','Number of distinct digital code values for a channel or sample; distinct from bitrate.','10-bit footage can preserve smoother tone gradients than an otherwise comparable 8-bit source.',56),
      ('Burn-in caption','Text rendered permanently into the exported video pixels.','Captions remain visible in a player even without external subtitles.',68),
      ('Camera-original','The captured original file or card structure to retain independently of proxies or transcodes.','Keep camera media untouched before creating editing proxies.',14),
      ('Channel mapping','Assignment of source audio channels to timeline channels; incorrect mapping can mute or duplicate a microphone.','Assign a recorded mono lav channel appropriately before a dialogue cut.',40),
      ('Chromatic aberration','Wavelength-dependent color fringing, sometimes a lens defect and sometimes a stylized effect.','Inspect red/cyan fringes around high-contrast edges before sharpening.',49),
      ('Closed GOP','Compression group that can be decoded without referencing pictures from a different group; useful for some interchange workflows.','Seek and transcode behavior differs between GOP settings.',84),
      ('Color gamut','Range of reproducible colors in a defined color space.','Wide-gamut camera footage must be mapped appropriately for Rec.709 delivery.',56),
      ('Color metadata','Tags describing how image values should be interpreted by a decoder or display pipeline.','Wrong primaries or transfer tags may make an exported file appear different in a player.',61),
      ('Consolidation','Collecting or copying relevant files for project handoff, often with optional trimming depending on tool and media type.','Reopen the archived project from a disconnected drive to test links.',75),
      ('Constant frame rate (CFR)','A file whose presentation timestamps follow a regular target cadence, unlike VFR footage.','Transcode a drifting phone recording to an editing-friendly CFR intermediate.',13),
      ('Crossfade','Overlap or transition blending between two sources rather than an instantaneous cut.','Use a short equal-power audio crossfade to avoid an audible seam.',43),
      ('Debayer','Process of reconstructing color channels from a camera sensor mosaic, relevant to some RAW media.','RAW decode quality and controls depend on camera format and support.',72),
      ('Decode','Read compressed source frames into pictures or sound samples available for editing.','A CPU may struggle to decode 4K 10-bit long-GOP footage during scrubbing.',93),
      ('Deinterlace','Convert interlaced fields into progressive pictures, with possible motion or detail tradeoffs.','Inspect old broadcast material for combing before export.',87),
      ('Dither','Small controlled noise that can reduce visible quantization artifacts when changing precision.','Very smooth gradients can show banding in low-bit-depth delivery.',56),
      ('Dynamic range','Difference between the darkest useful detail and brightest recoverable values of a signal.','Log camera footage needs a suitable transform before creative grading.',56),
      ('Encoder preset','A collection of output settings; it is a starting point, not proof that delivery requirements are met.','Verify actual resolution, profile, color and audio against client specifications.',85),
      ('Field order','Whether even or odd scan lines are presented first in an interlaced signal.','Wrong field order can cause jerky motion in older formats.',87),
      ('Gamma','Informal term for a nonlinear relationship between encoded image values and displayed light; exact meaning depends on color pipeline.','Do not compensate for metadata mistakes with an arbitrary gamma adjustment.',61),
      ('Gamut mapping','Transforming colors from one gamut to another while managing out-of-range values.','Map wide-gamut footage to the chosen SDR output without arbitrary clipping.',56),
      ('Headroom','Margin below clipping reserved for louder peaks or later processing.','Leave transient margin when mixing speech over music.',45),
      ('In point','First selected frame or position of a clip for an edit.','Mark the start of usable action in the Source Monitor.',16),
      ('Intra-frame codec','Compression primarily operating within each frame rather than using temporal prediction across frames.','An edit-friendly intermediate may scrub more smoothly than a long-GOP camera codec.',85),
      ('Keyframe interpolation','Method used to calculate values between keyframes, such as linear versus eased motion.','Ease a lower third into position without an abrupt stop.',48),
      ('Letterbox','Horizontal bars created when a wider image is fitted inside a narrower display or frame.','Choose intentional letterboxing instead of stretching cinema footage.',3),
      ('Luminance','Approximate perceived brightness component, distinct from a simple average of RGB values.','Use waveform scopes to compare scene exposure.',55),
      ('Media offline','Project has a reference to source media, but it cannot currently resolve the file location.','Relink a moved folder while checking clip identity.',12),
      ('Multichannel audio','Audio carrying more than two discrete channels; routing depends on track and export mapping.','Confirm the intended channel layout before a broadcast master.',40),
      ('Nesting','Placing a sequence inside another sequence as one editable timeline item.','Nest a built title montage for higher-level placement.',28),
      ('Out point','End boundary of a selected source/sequence range; editors may treat frame-accurate inclusive/exclusive boundaries differently by operation.','Check the exact selected frame count instead of assuming timecode math.',16),
      ('Pixel aspect ratio','Width-to-height shape of individual stored pixels; modern HD/UHD is often square pixel.','Legacy anamorphic footage needs correct interpretation.',3),
      ('Pillarbox','Vertical sidebars when narrower footage is shown in a wider frame without stretching.','A portrait clip may need reframing rather than black sidebars.',3),
      ('Pre-roll','Material or time before the main recorded action, used for handles or sync.','Retain a few seconds before the slate/clap in original footage.',69),
      ('Proxy attachment','Link from the original media object to a lightweight edit copy; original media remains authoritative for normal final export.','Toggle proxies, then inspect final output at original resolution.',71),
      ('Quantization','Mapping values onto discrete code levels; insufficient precision can produce banding or audio noise.','Gradient artifacts become more obvious after aggressive compression.',85),
      ('Render preview','Temporary computed media for smoother playback; using previews in exports requires attention to preview quality and settings.','A green timeline render bar does not prove the final H.264 export settings.',83),
      ('Safe margins','Guides for keeping critical text and imagery away from cropped edges or platform overlays.','Preview captions on the final vertical-phone layout.',62),
      ('Scene-referred','Image values describing captured scene light before a display rendering transform, depending on the color system.','Preserve Log/HDR interpretation before applying a creative look.',56),
      ('Sequence timebase','Frame-rate ruler used by the editing timeline; distinct from source frame rate and export frame rate.','A 25 fps sequence counts output positions in 25 frames per second.',15),
      ('Shutter angle','Exposure-time representation affecting motion blur; a 180-degree shutter nominally means half-frame exposure.','Different motion blur makes two cameras harder to match.',29),
      ('Source monitor','Panel for examining source media and marking a usable source range before an edit.','Set source In and Out points before Insert.',16),
      ('Sync lock','Track setting influencing how ripple operations preserve downstream timing across tracks.','A locked-off audio track can create unintended sync if ripple logic is misunderstood.',26),
      ('Timecode rollover','Frame address advancing from the last frame number of a second to the next second.','At 25 fps, 00:00:03:24 is followed by 00:00:04:00.',2),
      ('Timeline instance','A use of source media with its own timing/effects/position; it is not a rewritten camera file.','Two cuts from one video can have different color corrections.',1),
      ('Track targeting','Selection of sequence tracks for certain editing and navigation commands, distinct from source patching.','Check target V1/A1 before keyboard editing.',18),
      ('Transfer function','Mapping between numeric image values and represented brightness, such as SDR gamma or HDR PQ/HLG.','Matching primaries alone does not ensure correct HDR-to-SDR display.',56),
      ('True peak','Estimated peak amplitude between digital samples as well as at sample instants; relevant to encoding and distribution.','Choose a delivery ceiling that includes intersample overs.',45),
      ('VFR','Variable frame rate: video frames arrive at varying time intervals; some sources need conversion for dependable sync.','Phone footage that drifts against separate recorder audio.',13),
      ('White balance','Adjustment accounting for the color of scene illumination, often using neutral references.','Match cameras before applying stylistic color changes.',57),
      ('YUV / YCbCr','Video representations separating luma-like and chroma-like components; YCbCr is the digital family commonly used by encoded video.','4:2:0 sampling stores less chroma spatial detail than 4:4:4.',84),
    ]
    existing={g['term'].casefold() for g in glossary}
    for term,definition,example,n in terms:
        if term.casefold() not in existing:
            glossary.append({'term':term,'definition':definition,'example':example,'lesson':f'L{n:03}'})
            existing.add(term.casefold())
    glossary.sort(key=lambda g:g['term'].casefold())
    # New tests begin with the observable symptom and isolate a single variable before destructive changes.
    extra_diagnostics=[
      ('Source appears stretched or squeezed','Incorrect source pixel aspect ratio, sequence frame shape or scale settings','Inspect the clip properties and sequence dimensions; compare with a known-correct image; reset one transform on a duplicate sequence','Circles remain round and edge crop is intentional','Record aspect ratio and pixel interpretation at ingest','Changing sequence settings can alter existing graphics', 'L003'),
      ('Captions drift after ripple changes','Captions were created before a major structural re-edit or not included in the operation','Duplicate sequence; compare captions against speech at start, middle and end; regenerate or retime the affected caption range','Words appear during the corresponding spoken phrase in exported playback','Lock picture and dialogue timing before final caption QC','Caption track fixes do not correct bad source transcripts','L067'),
      ('Proxy toggle changes framing','Proxy has mismatched frame size, pixel ratio, rotation metadata or time alignment','Compare proxy/original at a recognizable frame, inspect both properties and recreate a matching proxy if needed','Toggle between attached original and proxy without composition jump','Make proxies using consistent ingest and frame alignment','Replacing proxies can invalidate previous QC notes','L071'),
      ('Transition unexpectedly short or absent','Insufficient outgoing or incoming source handles, clip boundary or incompatible edit','Trim away from clip boundary on a disposable copy; inspect source In/Out and transition alignment','A controlled transition has the requested duration and no repeated endpoint freeze','Reserve handles while shooting and selecting shots','Creating handles can consume usable frames or change cut point','L051'),
      ('Nested timeline has unexpected audio','Duplicate audio from parent/nest or wrong audio channel mapping','Solo parent and nested tracks separately; inspect source sequence and channel type','Only intended bus/track reaches the master output','Name audio buses and define routing before nesting','Removing duplicate audio can disrupt transition timing','L028'),
      ('Waveforms missing or very slow','Audio conforming/cache activity, invalid media or cache path','Check playback first, then review cache state and a known-good PCM WAV; avoid deleting camera files','Waveform returns and decoded audio matches source','Keep cache volume writable with sufficient free space','Cache refresh may take time and consume disk space','L092'),
      ('Overlays disappear in vertical crop','Auto Reframe/crop composition excludes titles or graphics, or safe margins are wrong','Duplicate original sequence; compare text layer position and output crop; check phone interface safe areas','Every required label remains legible in exported vertical master','Use aspect-ratio-specific title layouts','Resizing the sequence may change effect and transform framing','L054'),
      ('Wrong language in transcription','Incorrect language selection, noisy recording, accents or unavailable service','Check transcript language settings, inspect source audio, compare proper nouns against recording','Corrected transcript matches speech and caption timestamps','Use a manual transcript quality-control pass for names and numbers','Corrections can change text-based edit selections','L065'),
      ('Multicam cut selects wrong microphone','Audio follows video when fixed source audio was intended, or mixed source routing','Inspect multicam audio-follow-video policy; test angle changes while monitoring meters','Camera angle changes do not unintentionally replace the selected primary mic','Establish one audio strategy before editing','Audio-follow-video can be appropriate for live music, so preserve alternate version','L070'),
      ('Title animation flickers or jitters','Subpixel motion, field handling, rasterization, overly small type or export scaling','Inspect at full-resolution Program Monitor and exported file; compare movement without effects','Motion remains readable and stable at target frame rate','Use sensible type size and avoid excessive thin-line motion','Subpixel adjustments can change graphic alignment','L062'),
      ('Film looks noisy after correction','High ISO source, elevated shadows, aggressive sharpening or denoise failure','Compare before/after with scopes and 100% view; disable one correction at a time','Texture and detail are acceptable without artificial smearing','Expose within camera limits and preserve clean masters','Heavy denoise may remove real fine details','L057'),
      ('Export file plays silently','Audio export disabled, missing channel mapping, muted audio or incompatible player','Verify Export Audio setting; import rendered file back into Premiere; check audio streams using a separate player','Reimport shows expected audio track and normal spoken playback','Use short preflight exports before long renders','Changing channel type can affect deliverable specifications','L088'),
      ('Burn-in captions unexpectedly double','Both captions are baked into pixels and a player sidecar/embedded caption layer is enabled','Inspect output in a caption-disabled player; check deliverable caption mode and sidecar naming','Exactly one intended caption presentation remains','Specify burn-in, embedded or sidecar per platform in delivery checklist','Removing sidecar can reduce accessibility options','L068'),
      ('Imported footage has no picture but audio works','Unsupported codec/profile, decode failure or VFR/device issue','Check container and codec separately; compare supported intermediate on a copy and system decode support','Video decodes consistently in Source Monitor and after export','Test new camera codec on the target workstation before a large shoot','Transcoding can alter metadata/timebase; keep camera-original','L013'),
      ('Project becomes unusually large or slow to open','Many linked assets, excessive sequences, high-resolution thumbnails or project corruption','Duplicate project; remove one high-cost bin on a test copy; compare load times','Project opens repeatably without losing necessary links','Organize Productions/sequence versions and periodic project backups','Consolidation or cleanup can break collaboration if done on shared original','L073'),
      ('Media Encoder queue does not match Premiere export','Different sequence state, preset, codec availability or stale queue items','Write down preset and output path; re-queue a short test section; compare exported metadata','Queued render matches agreed output settings and picture/audio state','Version-lock Media Encoder and document export preset per deliverable','Changing queue item may overwrite an earlier approved file','L089'),
      ('Dark border after stabilization','Stabilized edge translation exposes empty pixels and crop settings are insufficient','Toggle stabilization; inspect corners in motion; adjust crop/scale on a duplicate','No unwanted edge gaps throughout shot','Shoot extra framing margin for handheld shots','Scaling reduces effective picture detail','L052'),
    ]
    title_set={t['title'].casefold() for t in troubles}
    for title,causes,tests,confirm,prevention,side_effects,lesson in extra_diagnostics:
        if title.casefold() not in title_set:
            troubles.append({'id':f'T{len(troubles)+1:03}', 'title':title,'causes':causes,'tests':tests,'confirm':confirm,'prevention':prevention,'side_effects':side_effects,'lesson':lesson})
    extra_recipes=[
      ('Deliver a captioned 16:9 and 9:16 pair',[62,67,68,87,88],'Duplicate the locked landscape sequence instead of mutating it; design safe vertical text and reframe shots; choose whether each master requires burn-in or SRT sidecar; export both using clearly different names; review captions in actual players and verify no overlays cover them.'),
      ('A/B test hardware and software encoding',[83,84,85,86,90],'Duplicate the same fixed-duration sequence output task; export once using supported hardware encoding, once with software; record actual preset settings and export times; compare frames in motion and file metadata; keep the better conforming deliverable for the recipient.'),
      ('Rebuild a project after a disk migration',[9,12,75,91,96],'Duplicate the project and preserve old drive layout notes; move media in a predictable single directory tree; relink with a verified root file using metadata and visual spot checks; test three random timeline clips plus export; record the new paths in the archive handoff.'),
      ('Investigate sync drift in a long interview',[13,38,40,69,72],'Find synchronized clap or mouth-action marker near the start; compare audio against video near midpoint and end; measure drift direction before attempting repair; make an authorized CFR intermediate if the source timing is irregular; verify sync across entire final export.'),
      ('Create a conservative documentary paper edit',[31,34,36,65,66],'Correct source transcript against original speech; select passages without losing meaningful qualifiers; create the rough cut; inspect every automatic text cut in picture and sound; add only truthful and clearly relevant cutaways; export with a transcript/source attribution log.'),
      ('Check an HDR-to-SDR deliverable',[55,56,57,59,61,87,90],'Record the source primaries and transfer functions; choose a managed SDR output working space; normalize a representative highlight and skin-tone passage; compare scopes under consistent monitoring; export SDR and inspect file tags plus a reimported range.'),
      ('Build an accessible audio-first interview',[36,38,41,42,43,45,67],'Make an intelligible rough dialogue pass before cutting pictures; set clip gain and clean only harmful noise; use short natural ambiences across J/L cuts; mix to the specified loudness target; correct captions manually and check audio clarity on mono and headphones.'),
      ('Produce a client review package',[37,62,67,68,88,90,96],'Export a named, dated review file at an agreed picture frame rate; include slate/version and optional visible timecode with client approval; supply requested subtitle form and a change log; watch exported video end-to-end before sending; preserve last approved project and output separately.'),
      ('Diagnose a motion-effects performance regression',[29,47,48,49,52,93],'Save a safe duplicate and note actual preview FPS; toggle only one effect at a time and compare identical playhead span; evaluate reduced playback resolution and proxy decode separately; identify whether effects, source decode, storage or GPU is dominant; restore quality settings and inspect final export.'),
      ('Create a legally reusable graphics preset',[47,48,62,63,64],'Use an available licensed or system font and original vector shapes; animate one lower-third entry with measurable keyframe times; test at 16:9 and 9:16 frame sizes; save the reusable native graphic or template with dependencies listed; reopen in a new project to confirm portability.'),
    ]
    existing_recipes={r['title'].casefold() for r in recipes}
    for title,nums,procedure in extra_recipes:
        if title.casefold() not in existing_recipes:
            recipes.append({'id':f'R{len(recipes)+1:03}','title':title,'prerequisites':[f'L{i:03}' for i in nums], 'steps':procedure.split('; '), 'result':'A repeatable, inspectable Premiere workflow with a saved project version and explicit output or decision log.', 'check':'Inspect the actual saved/exported result and independently confirm each stated technical and editorial acceptance criterion.'})
    return {'glossary':len(glossary),'troubleshooting':len(troubles),'recipes':len(recipes)}
